// Validates what the parent workflow passed in. No network, no database, no logging of voucher data.
// The tenant, the actor e-mail and the role come from the verified session of the parent workflow (never from the message text);
// sp_agri_register_sale re-checks membership and the ADMIN role on its own.
const i = $input.first().json;
const stop = (output) => [{ json: { ok: false, output } }];

const tenant = Number(i.id_company);
if (!Number.isInteger(tenant) || tenant <= 0) return stop('⚠️ No pude identificar la empresa activa de tu sesión. Selecciónala en la plataforma y vuelve a intentar.');
if (typeof i.actor_email !== 'string' || i.actor_email.trim() === '') return stop('⚠️ No pude identificar a tu usuario. Vuelve a iniciar sesión.');

// Only an ADMIN of the company registers sales; cfdi-service is not called otherwise.
if (String(i.role || '').toUpperCase() !== 'ADMIN') return stop('⛔ Solo un administrador de la empresa puede registrar ventas por chat.');

const name = String(i.file_name || '').toLowerCase();
const type = String(i.file_type || '').toLowerCase();
if (!name.endsWith('.xml') || !['text/xml', 'application/xml', 'application/octet-stream'].includes(type)) {
  return stop('⚠️ Para registrar una venta adjunta la factura en formato XML.');
}
const b64 = i.xml_base64;
if (typeof b64 !== 'string' || b64.length === 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(b64)) return stop('⚠️ El archivo no es una factura CFDI 4.0 en XML válida.');
if (b64.length > 7200000) return stop('⚠️ El archivo es demasiado grande o tiene demasiados conceptos.');

return [{ json: { ok: true } }];

// Builds the ONLY text the user sees. Fixed Spanish texts, plain text. No model is involved and nothing is logged.
// Echoed from the voucher: folio, date, buyer name, kilograms, unit price, total and ticket (sanitized). Never the UUID, the XML or any seal.
const safe = (v, n) => String(v === undefined || v === null ? '' : v).replace(/[\u0000-\u001f\u007f<>`\[\]]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n || 80);
const money = (v) => { const n = Number(v); return Number.isFinite(n) ? n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : safe(v, 20); };
const qty = (v) => { const n = Number(v); return Number.isFinite(n) ? n.toLocaleString('en-US', { maximumFractionDigits: 6 }) : safe(v, 20); };
const reply = (output) => [{ json: { output } }];
const ran = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };

const TX = {
  unavailable: '⚠️ El servicio de facturas no está disponible por ahora. Intenta de nuevo en unos minutos.',
  disabled: '⚠️ El registro de ventas está desactivado temporalmente.',
  invalidFile: '⚠️ El archivo no es una factura CFDI 4.0 en XML válida.',
  unsupported: '⚠️ Solo registro facturas CFDI 4.0 de ingreso en pesos mexicanos.',
  invalidVoucher: '⚠️ La factura no es válida (timbre, RFC o importes). Revisa el archivo.',
  tooLarge: '⚠️ El archivo es demasiado grande o tiene demasiados conceptos.',
  forbiddenContent: '⚠️ El archivo contiene contenido no permitido.',
  storeFailed: '⚠️ No pude guardar el archivo original de la factura. Intenta de nuevo en unos minutos.',
  forbidden: '⛔ Solo un administrador de la empresa puede registrar ventas por chat.',
  notPalm: '⚠️ La empresa activa no es de palma.',
  issuerNotConfigured: '⚠️ La empresa no tiene un RFC emisor configurado para registrar ventas. Pide a la plataforma que lo configure.',
  issuerMismatch: '⚠️ El RFC emisor de la factura no corresponde a esta empresa. Verifica que seleccionaste la empresa correcta.',
  duplicate: '⚠️ No se pudo registrar la factura.',
  alreadyRegistered: 'ℹ️ Esta factura ya estaba registrada; no se hizo ningún cambio.',
  generic: '⚠️ No se pudo registrar la factura.',
};

const PARSE_TEXT = {
  NOT_XML: TX.invalidFile, INVALID_STRUCTURE: TX.invalidFile, INVALID_BODY: TX.invalidFile, INVALID_PROFILE: TX.invalidFile,
  UNSUPPORTED_VERSION: TX.unsupported, UNSUPPORTED_TYPE: TX.unsupported, UNSUPPORTED_CURRENCY: TX.unsupported,
  NOT_STAMPED: TX.invalidVoucher, INVALID_RFC: TX.invalidVoucher, INVALID_AMOUNT: TX.invalidVoucher, AMOUNTS_MISMATCH: TX.invalidVoucher,
  TOO_LARGE: TX.tooLarge, TOO_MANY_CONCEPTS: TX.tooLarge, PAYLOAD_TOO_LARGE: TX.tooLarge,
  DOCTYPE_FORBIDDEN: TX.forbiddenContent, INVALID_CHARS: TX.forbiddenContent,
};

const REASON_TEXT = {
  TIPO: 'solo se registran facturas de ingreso (tipo I)',
  CURRENCY: 'solo se aceptan pesos mexicanos (MXN)',
  PAYMENT_METHOD: 'solo se acepta pago en una sola exhibición (PUE)',
  CONCEPT_COUNT: 'la factura debe traer exactamente un concepto',
  UNIT: 'la unidad debe ser kilogramo (KGM)',
  QUANTITY: 'la cantidad o el precio unitario no son válidos',
  CONCEPT_AMOUNT: 'el importe del concepto no es válido',
  AMOUNTS: 'los importes no son válidos',
  AMOUNTS_MISMATCH: 'los importes no cuadran',
  AMOUNTS_MISMATCH_CONCEPT: 'el importe no coincide con cantidad × precio unitario',
  DATE_FUTURE: 'la fecha de la factura es futura',
  DATE_TOO_OLD: 'la factura tiene más de 365 días',
  BUYER_IS_ISSUER: 'el comprador no puede ser el emisor',
  PAYMENT_FORM: 'falta la forma de pago',
};

const entry = $('Validar Entrada').first().json;
if (!entry.ok) return reply(entry.output);

if (ran('Registrar Venta')) {
  const r = ($('Registrar Venta').first().json || {}).result;
  if (!r || typeof r !== 'object') return reply(TX.unavailable);

  if (r.status === 'OK') {
    const s = r.summary || {};
    const lines = ['✅ Venta registrada.'];
    const head = [];
    if (safe(s.folio, 40)) head.push('Folio ' + safe(s.folio, 40));
    if (safe(s.sale_date, 12)) head.push(safe(s.sale_date, 12));
    if (head.length) lines.push(head.join(' · '));
    if (safe(s.buyer_name, 120)) lines.push('Comprador: ' + safe(s.buyer_name, 120));
    lines.push(qty(s.quantity_kg) + ' kg a $' + money(s.unit_price) + '/kg');
    lines.push('Total: $' + money(s.total_amount) + ' MXN');
    if (safe(s.ticket_ref, 30)) lines.push('Ticket: ' + safe(s.ticket_ref, 30));
    const notes = [];
    for (const w of Array.isArray(r.warnings) ? r.warnings : []) {
      if (w === 'ticket_missing_or_unrecognized') notes.push('No encontré el número de ticket en el concepto; la venta quedó registrada sin ticket.');
      else if (w === 'ticket_already_used') notes.push('El ticket ' + safe(s.ticket_ref, 30) + ' ya está en otra venta activa de la empresa. Revisa que no sea un duplicado.');
      else if (w === 'previous_sale_voided') notes.push('Esta factura había sido anulada antes; se registró de nuevo.');
    }
    if (s.sat_status === 'SKIPPED_TEST') notes.push('Empresa de pruebas: el SAT no se verificó.');
    if (notes.length) lines.push('Avisos:', ...notes.map((n) => '• ' + n));
    return reply(lines.join('\n'));
  }
  if (r.status === 'ALREADY_REGISTERED') return reply(TX.alreadyRegistered);
  if (r.status === 'FORBIDDEN') return reply(TX.forbidden);
  if (r.status === 'NOT_PALM') return reply(TX.notPalm);
  if (r.status === 'ISSUER_RFC_NOT_CONFIGURED') return reply(TX.issuerNotConfigured);
  if (r.status === 'ISSUER_RFC_MISMATCH') return reply(TX.issuerMismatch);
  if (r.status === 'DUPLICATE') return reply(TX.duplicate);
  if (r.status === 'disabled') return reply(TX.disabled);
  if (r.status === 'INVALID_VOUCHER') {
    const reason = String(r.reason || '');
    if (reason === 'SAT_NOT_VALID') {
      const sat = ran('CFDI SAT Status') ? String(($('CFDI SAT Status').first().json || {}).status || '') : '';
      if (sat === 'CANCELADO') return reply('⚠️ No se pudo registrar la factura: está cancelada ante el SAT.');
      if (sat === 'NO_ENCONTRADO') return reply('⚠️ No se pudo registrar la factura: el SAT no la encontró.');
      return reply('⚠️ No pude verificar la factura con el SAT. Intenta de nuevo en unos minutos.');
    }
    return reply('⚠️ No se pudo registrar la factura: ' + (REASON_TEXT[reason] || 'datos del comprobante no válidos') + '.');
  }
  return reply(TX.generic);
}

if (ran('CFDI Store')) {
  const s = $('CFDI Store').first().json || {};
  return reply(s.status === 'invalid' || s.status === 'error' ? TX.storeFailed : TX.unavailable);
}

if (ran('CFDI Parse')) {
  const p = $('CFDI Parse').first().json || {};
  if (p.status === 'invalid' && typeof p.code === 'string') return reply(PARSE_TEXT[p.code] || TX.invalidFile);
  return reply(TX.unavailable);
}

return reply(TX.unavailable);
